-- SALY_FONDEO_LEGAL: legal feasibility matrix appended to existing six tax/financial scenarios.
-- Scope: only saly.escenarios SALY-ESC-011..016. No LF, no checkpoint transitions, no operational permits asserted.
BEGIN;
DO $pre$ DECLARE v_count int; BEGIN
 IF (SELECT count(*) FROM saly.programas_investigacion p JOIN saly.proyecto x ON p.proyecto_id=x.id
  WHERE p.codigo='SALY_FONDEO_LEGAL' AND x.codigo='SALY-001')<>1
 THEN RAISE EXCEPTION 'BLOCK_SALY_LEGAL_PROGRAM_BINDING'; END IF;
 SELECT count(*) INTO v_count FROM saly.escenarios
 WHERE codigo IN ('SALY-ESC-011','SALY-ESC-012','SALY-ESC-013','SALY-ESC-014','SALY-ESC-015','SALY-ESC-016')
 AND estado='BORRADOR' AND parametros->>'familia'='MODELOS_FONDEO_TRIBUTOS'
 AND NOT (parametros ? 'evaluacion_legal')
 AND parametros->'validacion'->>'legal'='PENDIENTE';
 IF v_count<>6 THEN RAISE EXCEPTION 'BLOCK_SALY_LEGAL_SCENARIO_PRECONDITION count=%',v_count; END IF;
END $pre$;

UPDATE saly.escenarios s
SET parametros=jsonb_set(s.parametros,'{evaluacion_legal}',source.payload,true),updated_at=now()
FROM (VALUES
('SALY-ESC-011','{"schema":"saly.legal_viability_assessment/v1","objective":"Dictaminar si cada modelo es juridicamente operable en Peru y los requisitos exactos de habilitacion, antes de declararlo viable comercialmente","date":"2026-10-15","estado":"EN_INVESTIGACION","dictamen_final":null,"dictamen_permitido":["APTO","APTO_CON_CONDICIONES","NO_APTO"],"criterio_final":"C1 normativa oficial revisada, C2 aplicado a contratos, permisos, actor, salario, costos y alternativas, C3 revision independiente PASS, brechas documentadas y condiciones comprobadas. No decidir SI/NO con sola inferencia comercial.","separacion_c1_c2_c3":{"C1":"Norma vigente, fuente oficial y requisitos de autorizacion","C2":"Aplicacion a cada esquema con contratos reales, estatutos, permisos y flujo; costo de cumplimiento","C3":"Revision juridica independiente contrastando fuentes y pronunciamiento PASS/FAIL"},"evidence_required_global":["Comprobar régimen del empleador, estatuto, poderes, libro de actas y fuente propia de capital.","Calificar quién origina, acreedor inicial/final, quién recibe pagos, quién asume mora y si el trabajador adeuda por préstamo o si existe pago laboral.","Revisar registro SBS 650-2024 por actividad habitual, UIF/PLAFT, eventual autorizaciones municipales/plataforma; no declarar exención por mera etiqueta ''beneficio laboral''.","Revisar que no exista captación de público ni publicidad de inversión sin título habilitante de SBS/SMV.","Comprobar contratos de trabajadores, prueba de aceptación electrónica y límites de descuentos por planilla ante la STC 02275-2023-PA/TC.","Evaluar privacidad y tratamiento de datos personales, portabilidad de cartera e información de acreedor.","Costear cumplimiento legal, registro, oficial de cumplimiento si aplica, contratos, auditoría y cobranza; mantener rubros separados de tributos y fondeo.","Emitir dictamen final por caso con fuente, hecho acreditado, requisito, prueba, responsable, costo, conclusión y dictamen independiente C3."],"c