('SALY-ESC-015','{"schema":"saly.legal_viability_assessment/v1","objective":"Dictaminar si cada modelo es juridicamente operable en Peru y los requisitos exactos de habilitacion, antes de declararlo viable comercialmente","date":"2026-10-15","estado":"EN_INVESTIGACION","dictamen_final":null,"dictamen_permitido":["APTO","APTO_CON_CONDICIONES","NO_APTO"],"criterio_final":"C1 normativa oficial revisada, C2 aplicado a contratos, permisos, actor, salario, costos y alternativas, C3 revision independiente PASS, brechas documentadas y condiciones comprobadas. No decidir SI/NO con sola inferencia comercial.","separacion_c1_c2_c3":{"C1":"Norma vigente, fuente oficial y requisitos de autorizacion","C2":"Aplicacion a cada esquema con contratos reales, estatutos, permisos y flujo; costo de cumplimiento","C3":"Revision juridica independiente contrastando fuentes y pronunciamiento PASS/FAIL"},"evidence_required_global":["Comprobar régimen del empleador, estatuto, poderes, libro de actas y fuente propia de capital.","Calificar quién origina, acreedor inicial/final, quién recibe pagos, quién asume mora y si el trabajador adeuda por préstamo o si existe pago laboral.","Revisar registro SBS 650-2024 por actividad habitual, UIF/PLAFT, eventual autorizaciones municipales/plataforma; no declarar exención por mera etiqueta ''beneficio laboral''.","Revisar que no exista captación de público ni publicidad de inversión sin título habilitante de SBS/SMV.","Comprobar contratos de trabajadores, prueba de aceptación electrónica y límites de descuentos por planilla ante la STC 02275-2023-PA/TC.","Evaluar privacidad y tratamiento de datos personales, portabilidad de cartera e información de acreedor.","Costear cumplimiento legal, registro, oficial de cumplimiento si aplica, contratos, auditoría y cobranza; mantener rubros separados de tributos y fondeo.","Emitir dictamen final por caso con fuente, hecho acreditado, requisito, prueba, responsable, costo, conclusión y dictamen independiente C3."],"checks_global":{"objeto_social_poderes":"NO_ACREDITADO","sbs_registro_o_no_aplicabilidad":"NO_ACREDITADO","captacion_publico_ausente":"NO_ACREDITADO","descuentos_planilla_derechos":"NO_ACREDITADO","contrato_valido_identifica_acreedor":"NO_ACREDITADO","proteccion_datos":"NO_ACREDITADO","costo_cumplimiento_pen":null},"costos_legalizacion":{"revision_estatuto_y_aprobacion_pen":null,"registro_sbs_si_aplica_pen":null,"cumplimiento_uif_plaft_si_aplica_pen":null,"honorarios_contratos_pen":null,"auditoria_y_reporte_pen":null,"cumplimiento_laboral_pen":null,"cumplimiento_proteccion_datos_pen":null,"operacion_servicing_pen":null},"comparacion":"Factibilidad legal primero, luego costos tributarios, de cumplimiento y financieros; ruta de menor carga empresarial si cumple.","unidad_principal":"SALY-LEG-07","conclusion_preliminar_condicionada":"La compra de acreencias por un fondo puede ser admisible según la ley y política de inversión del vehículo específico; no basta denominarlo fondo o señalar una SAFI en abstracto.","normativa_primaria":[{"norma":"DLeg. 862 TUO Ley de Fondos de Inversión","url":"https://www.smv.gob.pe/uploads/Ley_FondosInversion1.pdf","alcance":"Fondo de inversión y administradora; política de inversión y sujetos regulados"},{"norma":"Código Civil, arts. 1206,1207,1210,1215","url":"https://www.sat.gob.pe/Transparenciav3/Portals/0/Docs/NormasOtrasEntidades/DECRETO_LEGISLATIVO_295_v3.pdf","alcance":"Cesión de derechos, forma escrita, oponibilidad y límites"},{"norma":"STC 02275-2023-PA/TC, fundamentos 14-18","url":"https://www.tc.gob.pe/jurisprudencia/2025/02275-2023-AA.html","alcance":"No cabe descuento contractual que vulnere contenido protegido de remuneración"},{"norma":"Ley 26702, art. 11","url":"https://www.sbs.gob.pe/boletin/detalleboletin/idbulletin/1241","alcance":"Restricción para captación de dinero de terceros sin autorización"}],"preguntas_determinantes":["¿El reglamento de participación permite comprar cartera de préstamos personales de asalariados?","¿SAFI y órganos del fondo están autorizados y aprueban originación/servicing?","¿Cesión contemporánea es oponible a los deudores y compatible con la política de inversión?","¿Qué cobertura y garantía de cartera requiere el fondo?"],"documentos_y_evidencias_a_obtener":["Identidad del fondo, SAFI, autorización vigente y reglamento de participación","Política de inversión y acuerdos de comité sobre compra de créditos","Contrato de cesión, reglas de elegibilidad y aviso al trabajador","Contrato de servicing, recaudo, auditoría, riesgo y precios","Mapa de custodia de pagos y solvencia, remuneraciones protegidas"],"alternativa_si_no_apto":"Si reglamento del fondo no permite esa clase de activo, buscar un fondo habilitado o utilizar D/F bajo condiciones verificadas.","modelo":"E","capacidad_legal_empresa_no_financiera":"PENDIENTE_DE_VERIFICAR","necesita_constituir_fondo":"NO_SE_PRESUME; E/F dependen de fondo tercero existente","necesita_registro_sbs":"A_DETERMINAR_CON_BASE_EN_ACTIVIDAD_REAL","necesita_autorizacion_smv":"A_DETERMINAR_SE_GESTIONA_FONDO_O_SERVICIO_REGULADO","hecho_comercial":"El adelanto TuSueldoYa/SALY se estructura como prestamo personal cobrado via planilla, no como remuneracion anticipada abonada por empleador."}'::jsonb),
