La SAFI posee autorización y el comité aprueba la línea, plazo y garantías?","¿SALY está habilitada para colocar crédito a los trabajadores y cumplir deberes correspondientes?","¿La estructura evita modalidades prohibidas de captación o intermediación financiera?"],"documentos_y_evidencias_a_obtener":["Reglamento del fondo y aprobación de inversión/préstamo SALY","Contrato línea de crédito, tasa, garantía, renovación y covenants","Análisis SBS y fuente de capital de SALY","Contrato con trabajador, autorización de planilla, servicing","Mapa de pago, recuperación mensual, mora, liquidez y retornos"],"alternativa_si_no_apto":"Si el fondo no puede dar préstamos a SALY, evaluar adquisición de cartera E con reglamento compatible u otro financiador institucional.","modelo":"F","capacidad_legal_empresa_no_financiera":"PENDIENTE_DE_VERIFICAR","necesita_constituir_fondo":"NO_SE_PRESUME; E/F dependen de fondo tercero existente","necesita_registro_sbs":"A_DETERMINAR_CON_BASE_EN_ACTIVIDAD_REAL","necesita_autorizacion_smv":"A_DETERMINAR_SE_GESTIONA_FONDO_O_SERVICIO_REGULADO","hecho_comercial":"El adelanto TuSueldoYa/SALY se estructura como prestamo personal cobrado via planilla, no como remuneracion anticipada abonada por empleador."}'::jsonb)
) AS source(codigo,payload)
WHERE s.codigo=source.codigo AND s.estado='BORRADOR' AND s.parametros->>'familia'='MODELOS_FONDEO_TRIBUTOS';

DO $verify$ DECLARE n int; BEGIN
 SELECT count(*) INTO n FROM saly.escenarios
 WHERE codigo IN ('SALY-ESC-011','SALY-ESC-012','SALY-ESC-013','SALY-ESC-014','SALY-ESC-015','SALY-ESC-016')
 AND parametros->'evaluacion_legal'->>'estado'='EN_INVESTIGACION'
 AND parametros->'evaluacion_legal'->>'schema'='saly.legal_viability_assessment/v1'
 AND parametros->'evaluacion_legal'->>'dictamen_final' IS NULL
 AND jsonb_array_length(parametros->'evaluacion_legal'->'preguntas_determinantes')>=3
 AND jsonb_array_length(parametros->'evaluacion_legal'->'normativa_primaria')>=4
 AND parametros->'validacion'->>'legal'='PENDIENTE'
 AND resultados->>'estado_resultado'='PENDIENTE_VALIDACION_TRIBUTARIA'
 AND resultados->>'importe_tributos_pen' IS NULL;
 IF n<>6 THEN RAISE EXCEPTION 'BLOCK_SALY_LEGAL_MATRIX_READBACK %',n; END IF;
 IF (SELECT count(*) FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON u.id=c.unidad_id JOIN saly.programas_investigacion p ON p.id=u.programa_id
 WHERE p.codigo='SALY_FONDEO_LEGAL' AND c.estado='DONE')<>2
 THEN RAISE EXCEPTION 'BLOCK_SALY_LEGAL_CHECKPOINT_DRIFT'; END IF;
END $verify$;
COMMIT;
